#
# weather -- command-line parsing (report, forecast, sync).
# Generated by Appeal's PROCESSOR emitter (appeal/codegen3.py):
# one generic engine (appeal.processor) runs these tiny Converter
# classes -- register() declares the work, the engine consumes argv.
# Regenerate rather than edit.
#
# (Sample artifact: the command callables bind live at registration,
# and the appeal-API shim + full dispatch are the remaining precompile
# integration.)

from appeal.processor import Converter, Repeat, Processor, dispatch
from appeal.runtime import split, counter, accumulator, validate, UsageError


class Converter_report(Converter):
    def __init__(self):
        Converter.__init__(self, report)
    def register(self, processor):
        processor.prepend([
            self.Option('-u', 'units', str),
            self.Option('--units', 'units', str),
            self.Option('-v', 'verbose', bool),
            self.Option('--verbose', 'verbose', bool),
            self.Argument('city', str, True),
        ])

class Converter_forecast(Converter):
    def __init__(self):
        Converter.__init__(self, forecast)
    def register(self, processor):
        processor.prepend([
            self.Argument('city', str, True),
            self.Argument('days', int, False),
        ])

class Converter_sync(Converter):
    def __init__(self):
        Converter.__init__(self, sync)
    def register(self, processor):
        processor.prepend([
            self.Option('-v', 'verbose', counter(max=None, step=1)),
            self.Option('--verbose', 'verbose', counter(max=None, step=1)),
            self.Option('-t', 'tag', accumulator[str]),
            self.Option('--tag', 'tag', accumulator[str]),
            self.Option('-m', 'mode', validate('fast', 'safe', type=str)),
            self.Option('--mode', 'mode', validate('fast', 'safe', type=str)),
            self.Argument('source', split(':'), True),
        ])


commands = {
    'report': Converter_report,
    'forecast': Converter_forecast,
    'sync': Converter_sync,
}
